<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useWorkspace} from '../../stores/workspace'
import {useIntegration} from '../../stores/integration'
import {useStationData} from '../../composables/useStationData'
import {errorText,localApi} from '../../services/local/api'
import Panel from '../../components/Panel.vue'
import ServiceState from '../../components/local/ServiceState.vue'
import DatasetImport from '../../components/local/DatasetImport.vue'
const workspace=useWorkspace(),service=useIntegration(),scope=useStationData(),{stationId,stations,station,datasets,models,loading,loadingData,error}=scope
const ent=ref(workspace.context?.enterprise.id??''),net=ref(workspace.context?.network.id??''),seg=ref(workspace.context?.segment.id??''),name=ref(''),code=ref(''),saving=ref(false),saveError=ref('')
const networks=computed(()=>workspace.state.networks.filter(n=>n.enterpriseId===ent.value&&n.active)),segments=computed(()=>workspace.state.segments.filter(s=>s.networkId===net.value&&s.active))
watch(ent,()=>{net.value='';seg.value=''});watch(net,()=>seg.value='')
function apply(){if(workspace.contextFor(seg.value))workspace.select(seg.value)}
async function bind(){if(!workspace.context||saving.value)return;saving.value=true;saveError.value='';const c=workspace.context
 try{const s=await localApi.createStation({name:name.value.trim(),code:code.value.trim(),enterpriseId:c.enterprise.id,networkId:c.network.id,segmentId:c.segment.id,timezone:'Asia/Shanghai'});name.value='';code.value='';await scope.reload();if(workspace.context?.segment.id===c.segment.id)stationId.value=s.id}catch(e){saveError.value=errorText(e)}finally{saving.value=false}}
</script>
<template><div class="page-stack local-page"><div class="page-actions"><div><h2>管网管理</h2><p class="muted">绑定换热站、登记本站模型并导入运行数据。</p></div><span class="badge orange">本机服务</span></div><Panel title="企业 / 供热管网 / 管段选择"><div class="local-form-grid"><label>企业<select v-model="ent" aria-label="本机企业选择"><option value="">请选择企业</option><option v-for="e in workspace.state.enterprises.filter(e=>e.active)" :key="e.id" :value="e.id">{{e.name}}</option></select></label><label>供热管网<select v-model="net" :disabled="!ent" aria-label="本机供热管网选择"><option value="">请选择管网</option><option v-for="n in networks" :key="n.id" :value="n.id">{{n.name}}</option></select></label><label>管段<select v-model="seg" :disabled="!net" aria-label="本机管段选择"><option value="">请选择管段</option><option v-for="s in segments" :key="s.id" :value="s.id">{{s.name}}</option></select></label><button class="primary" :disabled="!workspace.contextFor(seg)" @click="apply">确认选择</button></div><p class="muted">组织 ID 需与本地后端注册表一致；页面选择不会将演示采样上传为真实数据。</p></Panel><ServiceState><template v-if="workspace.context"><Panel title="管段关联换热站"><p>当前管段：{{workspace.context.segment.name}}</p><p class="muted">模型检测换热站设备及控制状态，不检测埋地管道本体缺陷。</p><label>换热站<select v-model="stationId" :disabled="loading" aria-label="关联换热站"><option value="">{{loading?'加载中…':'请选择换热站'}}</option><option v-for="s in stations" :key="s.id" :value="s.id">{{s.name}} · {{s.code}}</option></select></label><p v-if="!loading&&!stations.length" class="empty">当前管段未绑定换热站，请先登记本站对象。</p><details><summary>登记换热站</summary><form class="local-form-grid mt" @submit.prevent="bind"><label>站点名称<input v-model="name" maxlength="60" required :disabled="saving" /></label><label>站点编码<input v-model="code" maxlength="30" required :disabled="saving" /></label><button class="primary" :disabled="saving||!name.trim()||!code.trim()">{{saving?'登记中…':'绑定到当前管段'}}</button></form><p class="muted">新站时区为 Asia/Shanghai。本站训练产物由后端登记，不自动套用示例模型。</p></details><p v-if="saveError" role="alert" class="error">{{saveError}}</p><p v-if="error" role="alert" class="error">{{error}} <button @click="scope.reload">重新加载</button></p></Panel><template v-if="station"><Panel title="本站模型"><p v-if="loadingData" role="status">正在读取模型…</p><div v-else class="table-wrap"><table><thead><tr><th>模型</th><th>版本</th><th>异常分数</th><th>持续性阈值</th><th>状态</th></tr></thead><tbody><tr v-for="m in models" :key="m.id+m.version"><td>{{m.name}} {{m.isDemo?'（示例）':''}}</td><td>{{m.version}}</td><td>{{m.scoreKind}}</td><td>{{m.cThr}}</td><td>{{m.status==='ready'?'可用':'不可用'}}</td></tr><tr v-if="!models.length"><td colspan="5" class="empty">本站尚无登记模型，请由模型开发者提供本站训练产物。</td></tr></tbody></table></div></Panel><Panel title="本站运行数据导入"><DatasetImport v-if="service.runtime?.capabilities.dataImport" :station="station" @imported="scope.reloadData"/><p v-else class="empty">本机后端尚未启用数据导入能力。</p></Panel><Panel title="历史数据集"><template #tools><button :disabled="loadingData" @click="scope.reloadData">刷新数据集</button></template><div class="table-wrap"><table><thead><tr><th>名称 / 版本</th><th>标准化采样</th><th>数据质量</th><th>操作</th></tr></thead><tbody><tr v-for="d in datasets" :key="d.id"><td>{{d.name}} / {{d.version}}</td><td>{{d.normalizedRowCount}} 行</td><td>{{d.status==='ready'?'可检测':'需修正'}}<ul v-if="d.issues.length"><li v-for="(i,j) in d.issues" :key="j">{{i.message}}</li></ul></td><td><RouterLink :to="{path:'/detections',query:{stationId:station.id,datasetId:d.id}}">查看采样与检测</RouterLink></td></tr><tr v-if="!datasets.length"><td colspan="4" class="empty">暂无本站数据，请导入 CSV。</td></tr></tbody></table></div></Panel></template></template><p v-else class="empty">请选择有效管段。</p></ServiceState></div></template>
